package workshop.vfx.paper.m8;

import java.util.Map;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static workshop.vfx.paper.m8.K1Fixture.*;
import workshop.vfx.delivery.QualityTier;
import workshop.vfx.math.core.Vec3;
import workshop.vfx.paper.core.ParticleSpec;

/** Six historical K1.1 case identifiers retained (historical method names); visual assertions now describe the owner-authorized vertical K1.2 correction. */
class K11RearArcTest {
    @Test void frontStaysClearForEveryTierPhaseAndBodyYaw(){for(var tier:QualityTier.values()){var f=new K1Fixture();f.start(tier);for(int age=0;age<240;age++){f.tick=100+age;f.position.get(A)[3]=age*17.5;var d=f.draft(A);for(var b:frame(d).batches())if(!b.layer().equals("halo"))for(int i=0;i<b.size();i++){Vec3 local=d.anchor().inverse().toWorld(b.point(i));assertEquals(-.85,local.z(),1e-10);}}}}
    @Test void arcIncludesBothEndsWithUniformSpacingAndDistinctTierSpans(){for(var tier:QualityTier.values()){var f=new K1Fixture();f.start(tier);var ring=frame(f.draft(A)).batches().getFirst();assertEquals(tier==QualityTier.SIMPLE?12:tier==QualityTier.BALANCED?16:20,ring.size());for(int i=0;i<ring.size();i++){double a=2*Math.PI*i/ring.size();assertEquals(1.05*Math.cos(a),ring.x(i),1e-12);assertEquals(65.25+1.05*Math.sin(a),ring.y(i),1e-12);assertEquals(2.10*Math.sin(Math.PI/ring.size()),ring.point(i).sub(ring.point((i+1)%ring.size())).length(),1e-12);}assertTrue(ring.point(0).sub(ring.point(ring.size()-1)).length()>.2);}}
    @Test void waistCentroidRemainsBehindTheTurningPlayerThroughoutSway(){var f=new K1Fixture();f.start(QualityTier.HEAVY);for(int age=0;age<120;age++){f.tick=100+age;f.position.put(A,new double[]{12+age*.28,65,-8,age*9,80,-90});var d=f.draft(A);var ring=frame(d).batches().getFirst();Vec3 sum=Vec3.ZERO;for(int i=0;i<ring.size();i++)sum=sum.add(d.anchor().inverse().toWorld(ring.point(i)));Vec3 centre=sum.mul(1.0/ring.size());assertEquals(-.85,centre.z(),1e-10);assertEquals(0,centre.x(),1e-10);assertEquals(1.25,centre.y(),1e-10);}}
    @Test void swayHasNoLoopJumpAndSlowsAtBothTurnarounds(){var f=new K1Fixture();f.balanced();Vec3[] p=new Vec3[161];for(int age=0;age<=160;age++){f.tick=100+age;p[age]=frame(f.draft(A)).batches().get(1).point(0);if(age>0){double distance=p[age].sub(p[age-1]).length();assertTrue(distance<.053*(1.05/.78));assertEquals(p[1].sub(p[0]).length(),distance,1e-12);}}assertTrue(p[0].sub(p[80]).length()<1e-12);assertTrue(p[80].sub(p[160]).length()<1e-12);assertTrue(p[40].sub(p[0]).length()>1);}
    @Test void haloRetainsHeightRadiusAndSpinWithWiderParticleSeparation(){assertEquals(new ParticleSpec.Dust(0x5CE1FF,.55f),M8StyleCatalog.whitelist().get(M8StyleCatalog.CYAN_HALO));for(var tier:new QualityTier[]{QualityTier.BALANCED,QualityTier.HEAVY}){var f=new K1Fixture();f.start(tier);var halo=frame(f.draft(A)).batches().getLast();assertEquals(tier==QualityTier.BALANCED?6:8,halo.size());for(int i=0;i<halo.size();i++){assertEquals(66.15,halo.y(i),1e-12);assertEquals(.45,Math.hypot(halo.x(i),halo.z(i)),1e-12);assertTrue(halo.point(i).sub(halo.point((i+1)%halo.size())).length()>.34);}f.tick=120;var q=frame(f.draft(A)).batches().getLast();assertEquals(0,q.x(0),1e-12);assertEquals(.45,q.z(0),1e-12);}}
    @Test void tightBudgetStillEmitsOnlyRearArcPointsWithoutChangingSharedScheduling(){var f=new K1Fixture(Map.of("maxCallsPerTick",4,"maxCallsPerViewerPerTick",4),Map.of());f.start(QualityTier.HEAVY);for(int i=0;i<120;i++){f.run();assertFalse(f.sends.isEmpty());assertTrue(f.sends.size()<=4);for(var s:f.sends){assertEquals(workshop.vfx.paper.core.DemoStyleCatalog.END_ROD,s.style());assertEquals(-.85,s.z(),1e-12);assertEquals(1.05,Math.hypot(s.x(),s.y()-65.25),1e-12);}f.account();f.tick++;}assertEquals(1,f.schedules);assertEquals(120,f.plans);}
}
